export function publicationsFor(
  spy: PublicationSpy,
  seeds: readonly string[],
): ReadonlyArray<Publication> {
  return spy.mock.calls.filter(
    ([stated]) =>
      stated.length === seeds.length && seeds.every((seed, index) => stated[index] === seed),
  );
}

